# ------------------------------------------------------------------------------------------------ freeze

def code_files():
    import p1v4_freeze as FZ
    mods = set(FZ.local_modules(list(ENTRIES))) | {p.replace("\\", "/") for p in glob.glob("scripts/p1v4_*.py")}
    return sorted(mods) + list(SBATCH)


def freeze_files():
    fs = [f"{BB2}/l1/l1_new.pt", f"{BB2}/l1/scores_dev.json", f"{BB2}/l1/train_log.json", SETTINGS2,
          f"{RES2}/grounding_v06_dev.json", f"{RES2}/offsets_2d_dev.json", f"{RES2}/readout_2d_dev.json",
          f"{RES2}/reliability_step1_dev.json", f"{RES2}/preview_dev.json",
          *(f"{RES2}/{n}" for n in INDEPENDENT_RESULTS), *(f"{MODEL}/{n}" for n in MODEL_FILES),
          "docs/p1_v04_second_backbone_plan.md", "results/main_v04/freeze.json"]
    for d in ("readout", "grounding/allclass", "grounding/allclass2c", "grounding/allclass2d", "grounding/control",
              "grounding/extra"):
        fs += sorted(f"{BB2}/{d}/{n}" for n in os.listdir(f"{BB2}/{d}")
                     if n.endswith((".npz", ".json")) and "train" not in n)
    return fs + code_files()


def settings_diff(a, b, path=""):
    """Leaf paths where two settings trees differ."""
    if isinstance(a, dict) and isinstance(b, dict):
        return [p for k in sorted(set(a) | set(b), key=str)
                for p in (settings_diff(a.get(k), b.get(k), f"{path}/{k}") if k in a and k in b else [f"{path}/{k}"])]
    return [] if a == b else [path]


def freeze_make():
    import p1v4_freeze as FZ
    if os.path.exists(FREEZE2):
        raise SystemExit(f"{FREEZE2} exists: it is never overwritten (use `freeze amend`)")
    if not FZ.git_clean():
        raise SystemExit("the working tree has uncommitted changes: commit them before the record")
    st = json.load(open(SETTINGS2))["settings"]
    if FZ.nulls(st):
        raise SystemExit(f"open items in the settings: {FZ.nulls(st)}")
    diff = settings_diff(st, json.load(open("results/main_v04/freeze.json"))["settings"])
    outside = [p for p in diff if not p.startswith(L1_FAMILY_SETTINGS)]
    if outside:                                   # review m6: only the L1 family's thresholds may differ
        raise SystemExit(f"settings differ from the first backbone's record outside the L1 family: {outside[:5]}")
    files = freeze_files()
    missing = [f for f in files if not os.path.exists(f)]
    if missing:
        raise SystemExit(f"missing: {missing}")
    rec = {"kind": "second backbone, final", "made": time.strftime("%Y-%m-%d %H:%M:%S"),
           "git_commit": subprocess.run(["git", "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip(),
           "git_clean": True, "versions": FZ.versions(), "settings": st,
           "settings_differ_from_first_backbone": {"leaves": len(diff), "under": list(L1_FAMILY_SETTINGS)},
           "files": {f: {"sha256": FZ.sha256(f), "bytes": os.path.getsize(f)} for f in files}, "amendments": []}
    json.dump(rec, open(FREEZE2, "w"), indent=1)
    print(f"wrote {FREEZE2}: {len(files)} files ({sum(v['bytes'] for v in rec['files'].values()) / 1e9:.2f} GB); "
          f"settings differ from the first backbone's in {len(diff)} leaves, all under {L1_FAMILY_SETTINGS}")


def freeze_amend(names, reason):
    """After a bug fix (as the first backbone's amendment 13.2): re-hash only the named files, which must be in the
    record; the frozen settings must not change; the old and new hashes are appended."""
    import p1v4_freeze as FZ
    if not reason:
        raise SystemExit("amend needs --reason")
    if not FZ.git_clean():
        raise SystemExit("commit the fix first: the working tree has uncommitted changes")
    rec = json.load(open(FREEZE2))
    if json.load(open(SETTINGS2))["settings"] != rec["settings"]:
        raise SystemExit("the frozen settings would change: an amendment may only re-hash fixed files")
    entry = {"time": time.strftime("%Y-%m-%d %H:%M:%S"), "reason": reason, "files": {},
             "git_commit": subprocess.run(["git", "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()}
    for f in names:
        f = f.replace("\\", "/")
        if f not in rec["files"]:
            raise SystemExit(f"{f} is not in the record (amend only re-hashes recorded files)")
        new = {"sha256": FZ.sha256(f), "bytes": os.path.getsize(f)}
        entry["files"][f] = {"old": rec["files"][f], "new": new}
        rec["files"][f] = new
    rec["amendments"].append(entry)
    json.dump(rec, open(FREEZE2, "w"), indent=1)
    print(json.dumps(entry, indent=1))


def verify2(quiet=False):
    import p1v4_freeze as FZ
    rec = json.load(open(FREEZE2))
    bad = [(f, "missing" if not os.path.exists(f) else "changed") for f, v in rec["files"].items()
           if not os.path.exists(f) or os.path.getsize(f) != v["bytes"] or FZ.sha256(f) != v["sha256"]]
    if not quiet:
        print(f"{FREEZE2}: {len(rec['files'])} files, {len(bad)} missing or changed", flush=True)
    if bad:
        raise SystemExit(f"second-backbone freeze record mismatch ({len(bad)} files), first: {bad[:3]}")
    if json.load(open(SETTINGS2))["settings"] != rec["settings"]:
        raise SystemExit("settings_dev.json differs from the frozen settings")
    return rec


def freeze_athena():
    """The GPU job's hash list (review M2): from the record, the checkpoint, the base model and the code the job imports;
    fresh hashes of the test inputs uploaded after the freeze (no record covers them; also logged)."""
    import p1v4_freeze as FZ
    rec = verify2()
    keep = [f"{BB2}/l1/l1_new.pt", *(f"{MODEL}/{n}" for n in MODEL_FILES), *code_files()]
    lines = [f"{rec['files'][f]['sha256']}  {f}" for f in keep]
    post = [f"{BB2}/examples_test.json"] + sorted(p.replace("\\", "/") for p in glob.glob(f"{ITEMS}/test*.json"))
    lines += [f"{FZ.sha256(f)}  {f}" for f in post]
    with open(ATHENA_SHA, "w", newline="\n") as f:
        f.write("\n".join(lines) + "\n")
    print(f"wrote {ATHENA_SHA}: {len(keep)} files from the record, {len(post)} test inputs", flush=True)


def test_gate():
    """Both freeze records verified (the first backbone's code runs here; this record holds the second backbone's
    model, read-outs and settings) and the final unlock set."""
    import p1v4_data as D
    import p1v4_freeze as FZ
    if not D.final_unlocked():
        raise SystemExit("test commands need P1V4_FINAL_RUN=1 and the freeze records")
    rec1 = FZ.verify_or_stop()
    print("first backbone's freeze record: verified", flush=True)
    rec2 = verify2()
    return rec1, rec2


# ------------------------------------------------------------------------------------------------ binding

def patch(split):
    """The first backbone's final-run and report code pointed at this backbone: run folders (bb2_report.bind), the
    final runner and decision report (R), the package's results folder (G4b and G5 files); the second backbone's
    settings wherever that code reads the rehearsal record (dev) or the freeze record (test). Returns the settings."""
    import p1v4_final as PF
    import p1v4_freeze as FZ
    import p1v4_grounding_v06 as V6
    import p1v4_test_report as TR
    B.bind(BB2)
    PF.R = TR.R = BB2
    V6.RES = RES2
    V6.noise_reliance = lambda *a, **k: {"not run": NOT_RUN}
    for name in INDEPENDENT_RESULTS:              # read by the package from its results folder; rivals only
        if not os.path.exists(f"{RES2}/{name}"):
            shutil.copy2(f"{RES1}/{name}", f"{RES2}/{name}")
        if FZ.sha256(f"{RES2}/{name}") != FZ.sha256(f"{RES1}/{name}"):
            raise SystemExit(f"{RES2}/{name} differs from {RES1}/{name}")
    if split == "dev":
        FZ.REHEARSAL = SETTINGS2                  # its "settings" are this backbone's (bb2_report settings)
        return json.load(open(SETTINGS2))["settings"]
    rec1, rec2 = test_gate()
    st = rec2["settings"]
    FZ.verify_or_stop = lambda path=None: {**rec1, "settings": st}
    return st


def lay_out_final(split):
    """runs_bb2/final/<split>: the rivals' outputs as the final runner leaves them; on dev also the old head's scores
    and the read-out features from this backbone's dev outputs (on test those come from the forwards)."""
    F1, F2 = f"{BB1}/final/{split}", f"{BB2}/final/{split}"
    for sub in RIVALS_FINAL:
        if os.path.exists(f"{F2}/{sub}"):
            shutil.rmtree(f"{F2}/{sub}")
        shutil.copytree(f"{F1}/{sub}", f"{F2}/{sub}")
    if split == "dev":
        os.makedirs(f"{F2}/l1", exist_ok=True)
        shutil.copy2(f"{BB2}/l1/scores_dev.json", f"{F2}/l1/scores.json")
        z = B.natural_dev(BB2)
        keys = ("states", "ears", "q_win", "q_task", "q_gold", "p_old", "ids", "units", "parts", "real", "conf",
                "sec_mean", "sec_max")
        os.makedirs(f"{F2}/readouts", exist_ok=True)
        np.savez(f"{F2}/readouts/feats_natural.npz", **{k: z[k] for k in keys})
    print(f"laid out {F2}: rivals {', '.join(RIVALS_FINAL)}" + (", l1, readouts" if split == "dev" else ""), flush=True)


def grounding_inputs(split):
    """The package's backbone-independent inputs of a split (as bb2_report.copy on dev): API answers, local rivals'
    scores, groups, VoxTurn alone on the matched groups."""
    src, dst = f"{BB1}/grounding/{split}", f"{BB2}/grounding/{split}"
    os.makedirs(dst, exist_ok=True)
    n = 0
    for name in os.listdir(src):
        if name == "api" or name.startswith("local_") or name in ("groups.json", "voxturn_matched.json"):
            s, d = os.path.join(src, name), os.path.join(dst, name)
            if os.path.isdir(s):
                if os.path.exists(d):
                    shutil.rmtree(d)
                shutil.copytree(s, d)
            else:
                shutil.copy2(s, d)
            n += 1
    print(f"copied {n} entries from {src} to {dst}", flush=True)


# ------------------------------------------------------------------------------------------------ rehearsal (dev)

def rehearse():
    import p1v4_final as PF
    import p1v4_grounding_v06 as V6
    import p1v4_test_report as TR
    st = patch("dev")
    lay_out_final("dev")
    grounding_inputs("dev")
    stub = f"{RES2}/noise_dev.json"              # review m8: exercise the G5 stub branch (removed afterwards)
    json.dump({"G5": {"not_run": NOT_RUN}}, open(stub, "w"), indent=1)
    try:
        with B.Audit(deny=True):
            z = dict(np.load(f"{BB2}/final/dev/readouts/feats_natural.npz"))
            PF.readout_scores("dev", z, st)
            TR.run("dev", out_path=f"{RES2}/decision_dev_rehearsal.json", final=True)
            V6.main("dev", out=f"{RES2}/grounding_v06_dev_rehearsal.json", with_natural=True)
    finally:
        os.remove(stub)
    a = json.load(open(f"{RES2}/grounding_v06_dev.json"))["criteria"]
    b = json.load(open(f"{RES2}/grounding_v06_dev_rehearsal.json"))["criteria"]
    g5 = b.pop("G5 (own run)", None)
    same = json.dumps(a, sort_keys=True, default=str) == json.dumps(b, sort_keys=True, default=str)
    print(f"rehearsal: matched-condition criteria equal to the dev evaluation's: {same}; G5 row: {g5}", flush=True)


# ------------------------------------------------------------------------------------------------ test inputs (laptop)

def items():
    import soundfile as sf
    import p1v4_context as C
    import p1v4_data as D
    import p1v4_grounding as G
    import p1v4_l1 as L1
    import p1v4_readout as RO
    import p1v4_readout_2d as R2D
    test_gate()                                  # no binding: the inputs are read by the first backbone's code as is
    os.makedirs(ITEMS, exist_ok=True)
    t0 = time.time()
    # 1. the old head's scoring pass (= p1v4_final.run_l1: L1.examples), checked against its stored test scores
    ex, _ = L1.examples("test")
    ref = json.load(open(f"{BB1}/final/test/l1/scores.json"))
    got = {"|".join(map(str, e["id"])): sorted(Q_OF[t] for t, _ in e["qs"]) for e in ex}
    assert got.keys() == ref.keys(), "old-head examples: window ids differ"
    assert all(got[k] == sorted(ref[k]) for k in ref), "old-head examples: questions differ"
    json.dump([dict(e, id=list(e["id"])) for e in ex], open(f"{BB2}/examples_test.json", "w"))
    print(f"examples_test: {len(ex)} windows, {sum(len(e['qs']) for e in ex)} questions", flush=True)
    sets = {}
    # 2. natural test (= p1v4_final.readout_features), checked against its stored read-out features
    rows = D.load_rows("test")
    wins = D.windows_of(rows, "test")
    rows_by = {(r["unit"], r["version"]): r for r in rows}
    ctx = RO.Edited("test", {})
    out = []
    for w in wins:
        r = rows_by[w["key"]]
        text, asks = ctx.situation(r, w["k"], "full")
        qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
        snd = [s for s in ctx.point(r, w["k"])[3] if RO.in_window(s, w["t"])]
        out.append({"id": w["id"], "unit": w["unit"], "part": w["part"], "path": w["path"], "text": text,
                    "marker": "agent" if w["assistant_speaking"] else "user", "qs": qs,
                    "gold": [-1 if w["gold"].get(q) is None else
                             int(w["gold"][q] == ("stop" if q == "S" else "respond")) for q in qs],
                    "real": RO.is_real(r, w["t"]), "conf": max([s[3] for s in snd], default=-1.0)})
    z = np.load(f"{BB1}/final/test/readouts/feats_natural.npz")
    assert list(z["ids"]) == [it["id"] for it in out]
    assert list(z["q_task"]) == [q for it in out for q in it["qs"]]
    assert list(z["q_gold"]) == [g for it in out for g in it["gold"]]
    assert list(z["parts"]) == [it["part"] for it in out] and list(z["real"]) == [it["real"] for it in out]
    assert np.allclose(z["conf"], [it["conf"] for it in out])
    assert [it["path"] for it in out] == [e["path"] for e in ex], "scoring pass and read-out pass: different windows"
    assert [it["text"] for it in out] == [e["text"] for e in ex], "scoring pass and read-out pass: different texts"
    sets["testnat"] = out
    # 3. the package's ten conditions (= p1v4_grounding.l1_cmd test), checked against its stored test inputs
    rows_g, rows_by_g = G.load("test")
    groups = G.load_groups("test")
    keys = {(g["unit"], v, g["k"]) for g in groups for v in g["versions"]}
    wins_g = [w for w in D.windows_of(rows_g, "test") if (w["unit"], w["version"], w["k"]) in keys]
    M = G.matched_context(C.Context)
    part_of = {g["unit"]: g["part"] for g in groups}
    for cond in G.ALL_CONDS:
        cx = M("test", groups, cond, rows_by_g, final=True)
        out = []
        for w in wins_g:
            if G.is_move(cond) and part_of[w["unit"]] != "s_move":
                continue
            r = rows_by_g[(w["unit"], w["version"])]
            text, asks = cx.situation(r, w["k"], "full")
            qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
            snd = [s for s in cx.point(r, w["k"])[3] if RO.in_window(s, w["t"])]
            out.append({"id": w["id"], "unit": w["unit"], "part": w["part"], "path": w["path"], "text": text,
                        "marker": "agent" if w["assistant_speaking"] else "user", "qs": qs,
                        "gold": [-1 if w["gold"].get(q) is None else
                                 int(w["gold"][q] == ("stop" if q == "S" else "respond")) for q in qs],
                        "real": RO.is_real(r, w["t"]), "conf": max([s[3] for s in snd], default=-1.0),
                        "text_sha": G.sha(text)})
        z = np.load(f"{BB1}/grounding/test/l1_{cond}.npz")
        assert list(z["ids"]) == [it["id"] for it in out], cond
        assert list(z["text_sha"]) == [it["text_sha"] for it in out], f"{cond}: texts differ from backbone 1"
        assert list(z["q_task"]) == [q for it in out for q in it["qs"]], cond
        assert list(z["q_gold"]) == [g for it in out for g in it["gold"]], cond          # review m4
        assert list(z["parts"]) == [it["part"] for it in out] and list(z["real"]) == [it["real"] for it in out], cond
        assert np.allclose(z["conf"], [it["conf"] for it in out]), cond
        sets[f"testgrd_{cond}"] = out
    # 4. the decision offsets (= p1v4_readout_2d.offsets test): the first backbone's rendered test windows
    groups_o = [g for g in groups if g["part"] == "s_move" and rows_by_g[(g["unit"], "1")]["subset"] is None]
    ref_o = json.load(open(f"{RES1}/offsets_2d_test.json"))
    assert len(groups_o) == ref_o["n_groups"]
    assert {g["unit"] for g in groups_o} == set(ref_o["per_unit_right"]["2d"]["+0.0"]), "offset groups differ"
    cx = M("test", groups_o, "none", rows_by_g)
    for d in R2D.OFFSETS:
        sets[f"testoff_d{d:+.1f}"] = []
    for g in groups_o:
        for v in g["versions"]:
            r = rows_by_g[(g["unit"], v)]
            p = r["points"][g["k"]]
            text, asks = cx.situation(r, g["k"], "full")
            qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
            for d in R2D.OFFSETS:
                path = f"{BB1}/final/test/offsets/{g['unit']}_{v}_p{g['k']}_d{d:+.1f}.wav"
                assert os.path.exists(path), path
                if d == 0.0:                          # as on the first backbone's test day (amendment 13.4)
                    assert np.array_equal(sf.read(path, dtype="int16")[0], sf.read(p["window"], dtype="int16")[0])
                sets[f"testoff_d{d:+.1f}"].append(
                    {"id": f"{g['unit']}|{v}|{g['k']}", "unit": g["unit"], "part": "s_move", "path": path,
                     "text": text, "marker": "agent" if p.get("assistant_speaking") else "user", "qs": qs,
                     "gold": [-1 if p["gold"].get(q) is None else
                              int(p["gold"][q] == ("stop" if q == "S" else "respond")) for q in qs],
                     "real": False, "conf": -1.0, "text_sha": G.sha(text)})
    for name, out in sets.items():
        json.dump(out, open(f"{ITEMS}/{name}.json", "w"))
        print(f"{name}: {len(out)} windows, {sum(len(it['qs']) for it in out)} questions", flush=True)
    print(f"test items: {time.time() - t0:.0f} s; equal to the first backbone's stored test inputs (offsets: its "
          f"rendered windows, the original offset equal to the stored window)", flush=True)


# ------------------------------------------------------------------------------------------------ forwards (GPU)

def save_npz(path, z):
    """Write to a temporary name, then rename (review m1: a killed job leaves no partial file under the real name)."""
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path + ".part", "wb") as f:
        np.savez(f, **z)
    os.replace(path + ".part", path)


def forward(prefix, limit=None):
    """prefix "test": the test run into the first backbone's test layout under runs_bb2. prefix "dev" with limit n:
    the smoke run of this same code on the first n items of every dev set, into runs_bb2/smoke_dev (review M4)."""
    import soundfile as sf
    import torch
    import bb2_pipeline as P
    import bb2_voxtral as BV
    import p1v4_l1 as L1
    split = prefix
    root = BB2 if prefix == "test" else SMOKE
    if prefix != "test" and not limit:
        raise SystemExit("the dev smoke run needs a limit")
    jobs = [(f"{prefix}nat", 8, f"{root}/final/{split}/readouts/feats_natural.npz")]
    jobs += [(n[:-5], 1, f"{root}/grounding/{split}/l1_{n[len(prefix) + 4:-5]}.npz")
             for n in sorted(os.listdir(ITEMS)) if n.startswith(f"{prefix}grd_")]
    jobs += [(n[:-5], 1, f"{root}/offsets/{split}/l1_{n[len(prefix) + 4:-5]}.npz")
             for n in sorted(os.listdir(ITEMS)) if n.startswith(f"{prefix}off_")]
    ex = BV.load_examples(split)[:limit]
    sets = {name: json.load(open(f"{ITEMS}/{name}.json"))[:limit] for name, _, _ in jobs}
    n_paths = sum(1 for e in ex if BV.local_path(e["path"])) + sum(1 for its in sets.values() for it in its
                                                                if BV.local_path(it["path"]))
    print(f"pre-flight: every window found ({n_paths} paths); sets {', '.join(sets)}", flush=True)
    model = BV.build()
    L1.load_new_state(model, torch.load(f"{BB2}/l1/l1_new.pt", weights_only=True))
    model.eval()
    sp = f"{root}/final/{split}/l1/scores.json"
    if not os.path.exists(sp):                   # = p1v4_final.run_l1 (L1.score, its batch 8)
        t0 = time.time()
        sc = L1.score(model, ex)
        os.makedirs(os.path.dirname(sp), exist_ok=True)
        L1.save_scores(sc, sp + ".part")
        os.replace(sp + ".part", sp)
        print(f"old-head scoring pass: {len(sc)} windows, {time.time() - t0:.0f} s", flush=True)
    counts = np.bincount(P.SEC_OF, minlength=8).astype(np.float64)
    for name, bs, out in jobs:
        if os.path.exists(out):
            print(f"{name}: exists, skipped", flush=True)
            continue
        its = sets[name]
        H, E, SM, SX, QW, QT, QG, PO = [], [], [], [], [], [], [], []
        rebuild = 0.0
        t0 = time.time()
        for i in range(0, len(its), bs):
            chunk = its[i:i + bs]
            waves = torch.stack([torch.from_numpy(sf.read(BV.local_path(it["path"]), dtype="float32")[0])
                                 for it in chunk]).cuda()
            h, e, qw, po, sm, sx = P.forward_states_vx(model, waves, [it["text"] for it in chunk],
                                                       [it["marker"] for it in chunk],
                                                       [[TASK[q] for q in it["qs"]] for it in chunk])
            # amendment 4.1's check, for this backbone's unequal seconds (12 or 13 tokens): the window ears rebuilt
            # from the per-second ears (token-weighted mean, max of maxima)
            whole = np.concatenate([(sm * counts[None, :, None]).sum(1) / counts.sum(), sx.max(1)], 1)
            rebuild = max(rebuild, float(np.abs(whole - e).max()))
            if rebuild > 0.001:
                raise SystemExit(f"{name}: window ears rebuilt from the seconds differ by {rebuild:.4f} (> 0.001)")
            H.append(h.astype(np.float16))
            E.append(e.astype(np.float16))
            SM.append(sm.astype(np.float16))
            SX.append(sx.astype(np.float16))
            QW.append(qw + i)
            QT += [q for it in chunk for q in it["qs"]]
            QG += [g for it in chunk for g in it["gold"]]
            PO.append(po)
            if (i // bs) % (500 if bs > 1 else 1000) == 0:
                print(f"{name}: {i + len(chunk)}/{len(its)} windows {time.time() - t0:.0f} s", flush=True)
        z = {"states": np.concatenate(H), "ears": np.concatenate(E), "q_win": np.concatenate(QW),
             "q_task": np.array(QT), "q_gold": np.array(QG), "p_old": np.concatenate(PO),
             "ids": np.array([it["id"] for it in its]), "units": np.array([it["unit"] for it in its]),
             "parts": np.array([it["part"] for it in its]), "real": np.array([it["real"] for it in its]),
             "conf": np.array([it["conf"] for it in its]), "sec_mean": np.concatenate(SM),
             "sec_max": np.concatenate(SX)}
        if not name.endswith("nat"):
            z["text_sha"] = np.array([it["text_sha"] for it in its])
        if name.endswith("nat"):                 # amendment 4.1: the old head bit for bit equal to the scoring pass,
            sc = json.load(open(sp))             # checked before the file is written (review m1)
            diff = max(abs(sc[its[w]["id"]][q] - float(p)) for w, q, p in zip(z["q_win"], z["q_task"], z["p_old"]))
            print(f"old head, read-out pass vs scoring pass: max |diff| {diff}", flush=True)
            if diff != 0.0:
                raise SystemExit("the read-out pass's old head differs from the scoring pass (must be identical)")
        save_npz(out, z)
        print(f"{name} done: {len(its)} windows, {len(QT)} questions, {time.time() - t0:.0f} s; window ears rebuilt "
              f"from the seconds within {rebuild:.6f}", flush=True)


def smoke_check():
    """The smoke outputs against the stored dev outputs of the same items (same code path, same GPU type)."""
    B.bind(BB2)                                   # natural_dev reads the bound read-out folder
    worst = {}

    def cmp(tag, a, b, keys):
        for k in keys:
            x = np.asarray(a[k])
            y = np.asarray(b[k])[:len(x)]
            if x.dtype.kind in "fc":
                worst[f"{tag} {k}"] = float(np.abs(x.astype(np.float64) - y.astype(np.float64)).max())
            else:
                worst[f"{tag} {k}"] = 0.0 if list(x) == list(y) else 1.0
    sc = json.load(open(f"{SMOKE}/final/dev/l1/scores.json"))
    ref = json.load(open(f"{BB2}/l1/scores_dev.json"))
    worst["scores"] = max(abs(v[q] - ref[k][q]) for k, v in sc.items() for q in v if v[q] is not None)
    a = dict(np.load(f"{SMOKE}/final/dev/readouts/feats_natural.npz"))
    b = B.natural_dev(BB2)
    nq = len(a["q_task"])
    cmp("devnat", a, {k: (v[:nq] if k in ("states", "q_task", "q_gold", "p_old", "q_win") else v) for k, v in b.items()},
        ("ids", "q_task", "q_gold", "q_win", "p_old", "states", "ears", "sec_mean", "sec_max"))
    for f in sorted(glob.glob(f"{SMOKE}/grounding/dev/l1_*.npz")) + sorted(glob.glob(f"{SMOKE}/offsets/dev/l1_*.npz")):
        rel = f[len(SMOKE) + 1:].replace("\\", "/")
        a, b = dict(np.load(f)), dict(np.load(f"{BB2}/{rel}"))
        nq = len(a["q_task"])
        cmp(rel, a, {k: (v[:nq] if k in ("states", "q_task", "q_gold", "p_old", "q_win") else v) for k, v in b.items()},
            ("ids", "q_task", "q_gold", "q_win", "p_old", "states", "ears", "sec_mean", "sec_max", "text_sha"))
    big = {k: v for k, v in worst.items() if v > 1e-3}
    print(json.dumps({"compared": len(worst), "max": max(worst.values()), "above 1e-3": big}, indent=1), flush=True)
    if big:
        raise SystemExit("smoke outputs differ from the stored dev outputs")


